-- =====================================================================================================
-- PILOTAGE BTS SCBH  ·  mise à jour 17 : DÉTAIL DES SAVOIRS ASSOCIÉS
-- Ajoute à chaque savoir associé le détail du référentiel (annexe I b, § 3) : les contenus (savoirs, connaissances,
-- concepts, notions, méthodes) et les limites de connaissances.
--
-- À exécuter UNE fois dans Supabase : SQL Editor → New query → coller tout ce fichier → Run.
-- (Relancer le script ne casse rien : il réécrit le même détail.)
-- =====================================================================================================

alter table public.savoirs add column if not exists contenus text[] not null default '{}';
alter table public.savoirs add column if not exists limites  text   not null default '';

update public.savoirs set contenus = array[$t$les essences bois de la construction$t$, $t$les propriétés physiques, mécaniques, anatomiques$t$, $t$la durabilité des bois et dérivés$t$, $t$la finition des bois$t$]::text[], limites = $t$Essences usuelles de la construction (on se limitera à une dizaine d’essences).
