update public.savoirs set contenus = array[$t$semelles filantes$t$, $t$radiers$t$, $t$plots$t$, $t$semelles isolées$t$, $t$pieux$t$, $t$vide sanitaire$t$, $t$dalle sur terre-plein$t$]::text[], limites = $t$Caractéristiques technologiques : domaine d’utilisation ; conditions d’adaptation à un projet ; performances structurelles ; techniques et particularités de mise en œuvre ; interface avec le projet bois ; influence sur le projet bois.$t$ where code = 'S11-11';
update public.savoirs set contenus = array[$t$construction maçonnée$t$, $t$construction en béton$t$, $t$construction métallique$t$]::text[], limites = $t$Caractéristiques technologiques : domaine d’utilisation ; conditions d’adaptation à un projet ; performances structurelles ; techniques et particularités de mise en œuvre ; interface avec le projet bois ; influence sur le projet bois.$t$ where code = 'S11-12';
update public.savoirs set contenus = array[$t$chauffage$t$, $t$renouvellement air$t$, $t$éclairage$t$, $t$sécurité (incendie, intrusion)$t$, $t$réseaux$t$, $t$…$t$]::text[], limites = $t$Caractéristiques technologiques des équipements : domaine d’utilisation ; principes de fonctionnement ; conditions d’adaptation à un projet ; interface avec le projet bois ; influences des choix sur le projet bois.$t$ where code = 'S11-13';
update public.savoirs set contenus = array[$t$EC0 – EC1$t$, $t$permanent$t$, $t$variable : neige, vent, exploitation, entretien$t$, $t$provisoire en phase de manutention et de levage$t$, $t$combinaisons de chargements$t$]::text[], limites = $t$Charges climatiques appliquées sur un bâtiment de géométrie simple (normalisation, réglementation, documentation technique).
Points singuliers (accumulation de neige, partie ouverte, charges d’équipement, charges d’entretien).
Nota : la sollicitation du vent pourra être étudiée à partir de feuilles de calcul ou de logiciels.
Combinaisons de charges représentatives.
Nota : dans le cas d’une définition manuelle des combinaisons de charges, on se limitera à deux charges variables (charge permanente et deux charges variables).$t$ where code = 'S12-1';
update public.savoirs set contenus = array[$t$identification du système porteur : porteur secondaire, porteur principal, stabilité$t$, $t$modélisation de la géométrie$t$, $t$modélisation des liaisons externes et internes à la structure$t$, $t$modélisation des actions mécaniques dues au chargement et appliquées au modèle de structure$t$, $t$influence de la modélisation sur le comportement mécanique$t$, $t$hypothèses liées aux matériaux et à la géométrie des barres (classe de résistance, classe de service, sections)$t$]::text[], limites = $t$Dans le cas d’une note de calcul simplifiée, la modélisation porte sur des barres ou des sous-ensembles plans.
Actions mécaniques ponctuelles, linéiques, surfaciques.
Actions transmissibles par une liaison.
Influence de la modélisation sur le transfert de charges.
On exclut : la modélisation complète en 3D ; les raideurs d’assemblage.$t$ where code = 'S12-2';
update public.savoirs set contenus = array[$t$nature des structures, isostatiques ou hyperstatiques$t$, $t$actions aux appuis (descentes de charges)$t$, $t$particularités de la stabilité des ouvrages : analyse de la circulation des efforts, solutions de stabilisation, stabilité par porteurs contreventés, stabilité par diaphragmes$t$]::text[], limites = $t$Nature des structures : poutres ; fermes, treillis, structures sur poteaux, poutre au vent, palées de stabilité ; portiques, arcs ; murs à ossature bois.
(Structures isostatiques) Actions de liaisons par une méthode analytique. Les méthodes graphiques peuvent être abordées.
(Structures hyperstatiques de degré 1) On se limitera à la recherche des actions de liaison en introduisant une équation supplémentaire issue du principe de superposition : résolution d’une poutre sur 3 appuis équidistants, résolution d’une poutre encastrée avec un appui en bout…$t$ where code = 'S12-3';
update public.savoirs set contenus = array[$t$hypothèses$t$, $t$caractéristiques mécaniques : bois, dérivés du bois (EWP, Engineered Wood Products), béton, métal…$t$, $t$détermination de la position d’un centre de gravité et du moment quadratique d’une section droite$t$, $t$efforts internes, sollicitations$t$, $t$compression – traction axiale – compression traction transversale – fendage – cisaillement longitudinal – flexion – sollicitations composées$t$, $t$instabilités de flambement et de déversement$t$, $t$déplacement et déformation des structures$t$]::text[], limites = $t$Performances des matériaux usuels de la construction.
Diagrammes de l’effort normal, de l’effort tranchant et du moment fléchissant d’une section droite.
Domaine élastique et domaine plastique, définition de la limite élastique, de la contrainte de rupture, du module d’élasticité, de l’allongement élastique.
Modes de rupture : ruptures fragiles et ruptures ductiles.
Contraintes de compression, traction, cisaillement, flexion.
Influence des phénomènes de flambement et de déversement. Influence du fluage sur les déformations.
Détermination des longueurs de flambement et de déversement. Préconisation des dispositifs qui limitent le flambement et le déversement.
Calcul des coefficients réglementaires du déversement et du flambement à l’aide de moyens informatisés et/ou d’abaques.
Exploitation des résultats d’un logiciel de résistance des matériaux (par exemple commenter des graphes d’efforts…).$t$ where code = 'S12-4';
update public.savoirs set contenus = array[$t$descentes de charges sur un assemblage$t$, $t$modélisation de l’assemblage (assemblages qui transmettent des efforts, assemblages qui transmettent des efforts et des moments)$t$, $t$performances des solutions technologiques usuelles (pointes, boulons, broches, vis, crampons, anneaux, agrafes, goujons, assemblages traditionnels…)$t$, $t$performances des murs à ossature bois avec voiles travaillants$t$, $t$analyse des modes de défaillance des assemblages$t$]::text[], limites = $t$Efforts à reprendre par un assemblage (à partir d’un modèle numérique, lorsque le problème est complexe).
Solution technologique d’assemblage en prenant en compte les dispositions réglementaires des assembleurs (conditions de pince).
Cheminement des efforts dans l’assemblage.
Conditions de défaillance de l’assemblage et détermination des vérifications à effectuer.$t$ where code = 'S12-5';
update public.savoirs set contenus = array[$t$EC5 : conditions de résistance barres et structures$t$, $t$EC5 : conditions de déformation barres et structures$t$, $t$EC5 : conditions de résistance de l’assemblage (plan cisaillé, nombre efficace, effets localisés…)$t$, $t$EC5 : vérifications de la résistance (barres, structures et assemblages…) avec prise en compte des instabilités$t$, $t$EC5 : vérifications des déformations (barres et structures)$t$, $t$EC8 (partie bois) : comportements des structures bois ; dispositions réglementaires sismiques$t$, $t$EC3 : vérifications en cisaillement et pression diamétrale des attaches métalliques de ferrures$t$]::text[], limites = $t$Détermination de la résistance réglementaire attendue des sollicitations (compression, traction, cisaillement, fendage, flexion, sollicitations composées) avec prise en compte des coefficients réglementaires.
Détermination de la résistance réglementaire attendue des assemblages avec prise en compte des coefficients réglementaires et des particularités des assemblages (plans cisaillés, nombre efficace, effet de la disposition).
Détermination de la déformation réglementaire attendue des barres ou des structures étudiées avec prise en compte du fluage.
Calcul des taux de travail et de déformation de la vérification.
Exploitation des vérifications effectuées par un logiciel de résistance des matériaux.
Particularités de comportement des structures bois aux effets sismiques : modes de défaillances, dissipation de l’énergie, ancrages.
Prise en compte des dispositions réglementaires.$t$ where code = 'S12-6';
update public.savoirs set contenus = array[$t$technique d’utilisation d’un logiciel$t$, $t$données d’entrées et de sorties$t$, $t$chargements et combinaisons$t$, $t$interprétations et analyse des résultats$t$]::text[], limites = $t$Utilisation d’un logiciel de résistance des matériaux.
Description des données à entrer.
Interprétation des résultats : actions aux appuis ; graphes des efforts internes ; sollicitations ; déformations ; vérifications ; distinction des combinaisons les plus défavorables.$t$ where code = 'S12-7';
update public.savoirs set contenus = array[$t$réaction au feu, résistance au feu$t$, $t$vitesse de combustion$t$, $t$évolution de la résistance et de la stabilité$t$, $t$obligations réglementaires et vérifications : éléments linéaires, composants, assemblages$t$]::text[], limites = $t$Résistance d’une section soumise à un feu durant une durée réglementaire.
