update public.savoirs set contenus = array[$t$enjeux environnementaux$t$, $t$principes bioclimatiques$t$, $t$enveloppe et organisation des volumes des bâtiments$t$, $t$exposition, ensoleillement$t$, $t$dispositifs architecturaux et techniques$t$, $t$labels$t$]::text[], limites = $t$Principes bioclimatiques d’un projet : orientation du bâtiment ; compacité, disposition des pièces ; stratégie du chaud, stratégie du froid ; optimisation des apports solaires d’hiver ; protection solaire ; effet de masque ; protection solaire d’été ; distribution et qualité de la lumière ; qualité de l’air.$t$ where code = 'S13-1';
