update public.savoirs set contenus = array[$t$transfert hydrique$t$, $t$condensation de surface et dans l’épaisseur$t$, $t$valeurs de la perméabilité à la vapeur d’eau (perméabilité, perméance, mu, sd…)$t$, $t$diagramme de Glaser$t$, $t$solutions technologiques et matériaux spécifiques à l’hygrothermie$t$]::text[], limites = $t$Évaluation et localisation des risques de condensation dans une paroi.
